import React, { useEffect, useMemo, useState } from 'react';
import { ArrowLeft, Bell, Search, ShieldCheck, LayoutDashboard, Users, Store, Package, ShoppingBag, CreditCard, SlidersHorizontal, BarChart3, LockKeyhole, Settings, ChevronDown, TrendingUp, IndianRupee, AlertTriangle, Check, X, Eye, Ban, UserCheck, UserX, BadgeCheck, FileText, Download, CalendarDays, Sparkles, Flame, Gift, Sun, GraduationCap, Clock3, CircleHelp, SearchCheck, Trash2, Pencil, Plus, Filter, Activity, ShieldAlert, CircleDollarSign, MapPinned, Percent, Mail, KeyRound, Globe, Save, CheckCircle2 } from 'lucide-react';
